def recover_legacy_queue(apps, schema_editor):
    Analysis = apps.get_model('video_library', 'VideoAnalysis')
    Video = apps.get_model('video_library', 'Video')
    active = ['queued', 'preparing', 'processing', 'generating_results']
    seen = set()
    alias = schema_editor.connection.alias
    for analysis in Analysis.objects.using(alias).filter(status__in=active).order_by('-created_at', '-pk').iterator():
        if analysis.video_id in seen:
            analysis.status = 'cancelled'
            analysis.current_step = 'Superseded by an existing analysis request'
        else:
            seen.add(analysis.video_id)
            analysis.status = 'queued'
            analysis.current_step = 'Waiting for analysis worker'
            analysis.progress_percentage = 0
            analysis.raw_results = {'camera_view': 'unknown'}
        analysis.worker_token = None
        analysis.lease_expires_at = None
        analysis.save(using=alias)
    # Old upload checkboxes set only Video.ai_status. Preserve those requests too.
    for video in Video.objects.using(alias).filter(ai_status='queued').iterator():
        if video.pk not in seen:
            Analysis.objects.using(alias).create(
                video_id=video.pk, requested_by_id=video.uploaded_by_id,
                requested_skill=video.skill_name, analysis_source='pose',
                analysis_version='pose-evidence-1.0.0', current_step='Waiting for analysis worker',
                raw_results={'camera_view': video.camera_view},
            )
            seen.add(video.pk)
    Video.objects.using(alias).filter(pk__in=seen).update(ai_status='queued')


